  -- own down script while 057 stays applied
  SELECT count(*) INTO v_n FROM public.food_items
   WHERE source = 'usda' AND status = 'verified' AND status_reason LIKE 'rules\_v1 import:055 %';
  IF v_n <> 11986 THEN RAISE EXCEPTION '056 requires 055: % imported verified rows, expected 11986', v_n; END IF;
