-- ── §1 Search ───────────────────────────────────────────────────────────────────────────────────────────
-- Loads pg_trgm's library in this session: a non-superuser may only SET pg_trgm.* once it is loaded (052 §1).
SELECT extensions.similarity('a', 'a') AS pg_trgm_loaded;

-- No SET search_path on purpose: every name is pg_catalog-qualified, and a SET clause would stop the planner inlining
-- the function (measured on a local copy: ~35% slower searches, the trigram recheck runs it per candidate row).
CREATE FUNCTION public.food_search_text(t text)
RETURNS text
LANGUAGE sql
IMMUTABLE PARALLEL SAFE
AS $fn$
  SELECT pg_catalog.btrim(pg_catalog.regexp_replace(pg_catalog.regexp_replace(pg_catalog.lower(coalesce(t, '')),
         '[^[:alnum:][:space:]]', ' ', 'g'), '\s+', ' ', 'g'))
$fn$;
COMMENT ON FUNCTION public.food_search_text(text) IS
  'v1.2 Phase 7 (056). search_foods'' normalization (= macroResolver.normalizeName for ASCII): the expression of food_items_usda_local_trgm_idx.';
-- service_role needs EXECUTE: an UPDATE of an imported row (the resolver's last_used_at touch) re-evaluates the index expression
REVOKE EXECUTE ON FUNCTION public.food_search_text(text) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.food_search_text(text) TO service_role;

CREATE INDEX food_items_usda_local_trgm_idx ON public.food_items
  USING gin (public.food_search_text(name) extensions.gin_trgm_ops)
  WHERE source = 'usda' AND status = 'verified' AND normalized_name IS NULL;

CREATE FUNCTION public.search_usda_local(q text, k integer DEFAULT 5)
RETURNS TABLE (
  id uuid, name text, fdc_id bigint,
  calories_per_100g numeric, protein_per_100g numeric, carbs_per_100g numeric, fat_per_100g numeric, fiber_per_100g numeric,
  score real,          -- strict_word_similarity(q, name) in [0.3, 1]: a raw signal, not a confidence
  head_match boolean,  -- q is the name's head noun (its first comma part, singular or plural): "rice" -> "Rice, white, cooked"
  name_sim real,       -- similarity(q, name) over whole strings: the shorter, closer name first
  dataset text         -- foundation | sr | fndds (from 055's status_reason)
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
SET pg_trgm.strict_word_similarity_threshold = 0.3
AS $fn$
  WITH input AS (
    SELECT public.food_search_text(search_usda_local.q) AS qn,
           least(greatest(coalesce(search_usda_local.k, 5), 1), 10) AS lim
  ),
  hit AS (                                    -- the partial GIN index: imported (key-less, verified) USDA rows only
    SELECT fi.id, fi.name, fi.fdc_id,
           fi.calories_per_100g, fi.protein_per_100g, fi.carbs_per_100g, fi.fat_per_100g, fi.fiber_per_100g,
           fi.status_reason, i.qn,
           public.food_search_text(fi.name) AS t,
           public.food_search_text(pg_catalog.split_part(fi.name, ',', 1)) AS head
      FROM input i
      JOIN public.food_items fi
        ON i.qn OPERATOR(extensions.<<%) public.food_search_text(fi.name)
       AND fi.source = 'usda' AND fi.status = 'verified' AND fi.normalized_name IS NULL
     WHERE i.qn <> '' AND fi.calories_per_100g IS NOT NULL
  ),
  scored AS (
    SELECT h.*,
           extensions.strict_word_similarity(h.qn, h.t) AS score,
           extensions.similarity(h.qn, h.t) AS name_sim,
           pg_catalog.regexp_replace(h.head, 'e?s$', '') = pg_catalog.regexp_replace(h.qn, 'e?s$', '') AS head_match,
           pg_catalog.substring(h.status_reason, '^rules_v1 import:055 ([a-z]+):') AS dataset
      FROM hit h
  )
  SELECT s.id, s.name, s.fdc_id,
         s.calories_per_100g, s.protein_per_100g, s.carbs_per_100g, s.fat_per_100g, s.fiber_per_100g,
         s.score, s.head_match, s.name_sim, s.dataset
    FROM scored s
   ORDER BY s.score DESC, s.head_match DESC, s.name_sim DESC,
            CASE s.dataset WHEN 'foundation' THEN 1 WHEN 'sr' THEN 2 WHEN 'fndds' THEN 3 ELSE 9 END,
            s.id
   LIMIT (SELECT lim FROM input)
$fn$;
COMMENT ON FUNCTION public.search_usda_local(text, integer) IS
  'v1.2 Phase 7 (056). Ranked, deterministic search over the key-less USDA rows 055 imported. Server-only (service_role); read by '
  'the resolver when RESOLVER_USDA is local (or eval_only for the eval accounts). A pick is a reference_match: no private row.';
REVOKE EXECUTE ON FUNCTION public.search_usda_local(text, integer) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.search_usda_local(text, integer) TO service_role;

