CREATE TEMP TABLE _map056 (food_item_id uuid PRIMARY KEY, category text NOT NULL, note text NOT NULL) ON COMMIT DROP;
-- production vs replay from the rows 056 needs: the live verified rows its 'verified' measures are keyed to
CREATE TEMP TABLE _need056 (fdc_id bigint PRIMARY KEY) ON COMMIT DROP;
INSERT INTO _need056 VALUES (167587), (167598), (167672), (167802), (168157), (168166), (168538), (168871), (168914), (168917), (168920), (168930), (169013), (169032), (169085), (169134), (169248), (169305), (169364), (169400), (169589), (169677), (169732), (169868), (169910), (169926), (169977), (169988), (170050), (170114), (170187), (170291), (170375), (170393), (170463), (170491), (170591), (170727), (170737), (170785), (170795), (170886), (170934), (171044), (171280), (171328), (171583), (171595), (171638), (171646), (171706), (171911), (172182), (172187), (172231), (172241), (172451), (172686), (172699), (172711), (173180), (173190), (173206), (173210), (173282), (173304), (173305), (173418), (173431), (173459), (173468), (173865), (174119), (174155), (174260), (174524), (174584), (174648), (174832), (174907), (174998), (175084), (175207), (334536), (748967), (790577), (2705740), (2705825), (2706538), (2707430), (2708347), (2708730), (2709129), (2709130), (2709309), (2709631), (2710472);
DO $state$
DECLARE v_all bigint; v_have bigint; v_marker boolean := pg_catalog.to_regclass('backup._backup_food_items_053') IS NOT NULL;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE EXISTS (SELECT 1 FROM public.food_items fi WHERE fi.fdc_id = n.fdc_id AND fi.status = 'verified'))
    INTO v_all, v_have FROM _need056 n;
  IF v_have > 0 AND v_have < v_all THEN
    RAISE EXCEPTION '056: only % of the % live verified fdc_ids it keys have a verified row (re-take the snapshot and regenerate)', v_have, v_all;
  ELSIF v_have = v_all AND NOT v_marker THEN
    RAISE EXCEPTION '056: the live verified rows are here but backup._backup_food_items_053 is missing (053 rolled back, or its backup renamed or cleaned up)';
  ELSIF v_have = 0 AND v_marker THEN
    RAISE EXCEPTION '056: backup._backup_food_items_053 exists but none of the % live verified fdc_ids it keys has a verified row', v_all;
  END IF;
END $state$;
CREATE TEMP TABLE _state056 ON COMMIT DROP AS SELECT EXISTS (SELECT 1 FROM _need056 n JOIN public.food_items fi ON fi.fdc_id = n.fdc_id AND fi.status = 'verified') AS go;
