-- ── §3 Compare-and-swap, then insert ────────────────────────────────────────────────────────────────────
DO $cas$
DECLARE v_bad text; v_n bigint;
BEGIN
  IF NOT (SELECT go FROM _state056) THEN
    DELETE FROM _pu056 p WHERE NOT EXISTS (SELECT 1 FROM public.food_items fi WHERE fi.fdc_id = p.fdc_id AND fi.status = 'verified');
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RAISE NOTICE '056: migrations-only replay: % measures for live verified rows skipped (those rows do not exist here)', v_n;
  END IF;
  -- every fdc_id the rows are keyed by has a verified food row (055's, or a live verified row of the snapshot)
  SELECT string_agg(x.fdc_id::text, ', ' ORDER BY x.fdc_id) INTO v_bad
    FROM (SELECT DISTINCT fdc_id FROM _pu056) x
   WHERE NOT EXISTS (SELECT 1 FROM public.food_items fi WHERE fi.fdc_id = x.fdc_id AND fi.status = 'verified');
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '056: portion rows for fdc_ids with no verified row (re-take the snapshot and regenerate): %', pg_catalog.left(v_bad, 2000);
  END IF;
  -- no slot is taken already (054's fold-in rows are skipped by the generator; this proves it on the real table)
  SELECT string_agg(p.fdc_id || ' ' || p.unit || ' ' || p.size, ', ' ORDER BY p.fdc_id, p.unit, p.size) INTO v_bad
    FROM _pu056 p JOIN public.portion_units pu
      ON pu.fdc_id = p.fdc_id AND pu.unit = p.unit AND pu.size = p.size AND pu.status = 'active'
     AND pu.context IS NULL AND pu.region IS NULL;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '056: portion slots already taken: %', pg_catalog.left(v_bad, 2000); END IF;
  SELECT string_agg(DISTINCT p.fdc_id::text, ', ') INTO v_bad
    FROM _pu056 p JOIN public.portion_units pu ON pu.fdc_id = p.fdc_id AND pu.is_default AND pu.status = 'active'
   WHERE p.is_default;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '056: default servings already exist for: %', v_bad; END IF;
  -- the category map names verified imported rows and existing categories, and no row is mapped already
  SELECT string_agg(m.food_item_id::text, ', ') INTO v_bad
    FROM _map056 m LEFT JOIN public.food_items fi ON fi.id = m.food_item_id
   WHERE fi.id IS NULL OR fi.status <> 'verified' OR fi.normalized_name IS NOT NULL
      OR fi.status_reason NOT LIKE 'rules\_v1 import:055 %'
      OR NOT EXISTS (SELECT 1 FROM public.portion_categories c WHERE c.category = m.category)
      OR EXISTS (SELECT 1 FROM public.portion_category_map x WHERE x.food_item_id = m.food_item_id);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '056: category map rows that do not fit: %', pg_catalog.left(v_bad, 2000); END IF;
END
$cas$;

INSERT INTO public.portion_units (id, food_item_id, fdc_id, category, unit, size, grams, ml, context, region, is_default,
    is_unit_default, source, grade, confidence, source_ref, source_text, approved_by, status, evidence)
  SELECT id, food_item_id, fdc_id, category, unit, size, grams, ml, context, region, is_default, is_unit_default, source,
         grade, confidence, source_ref, source_text, approved_by, status, evidence
    FROM _pu056 ORDER BY id;
INSERT INTO public.portion_category_map (food_item_id, category, note)
  SELECT food_item_id, category, note FROM _map056 ORDER BY food_item_id;

-- ── §4 Self-checks (any failure rolls back everything above) ─────────────────────────────────────────────
DO $chk$
DECLARE
  v_bad text; v_n bigint; v_run jsonb[] := '{}'; v_cur jsonb; r record; v_go boolean := (SELECT go FROM _state056);
  v_probe text[] := ARRAY['rice', 'apple', 'chicken curry', 'oatmeal'];
BEGIN
  -- 1. the manifest (production; a replay has only the rows on 055's foods)
  SELECT string_agg(m.k || ' got ' || coalesce(g.n, 0) || ' expected ' || CASE WHEN v_go THEN m.n_prod ELSE m.n_replay END, '; ') INTO v_bad
    FROM (VALUES ('usda_foundation', 91, 88), ('usda_sr', 6606, 6465),
                 ('usda_fndds', 15778, 15760)) AS m(k, n_prod, n_replay)
    LEFT JOIN (SELECT source AS k, count(*) AS n FROM public.portion_units WHERE status IN ('active', 'proposed') GROUP BY 1) g ON g.k = m.k
   WHERE coalesce(g.n, 0) <> CASE WHEN v_go THEN m.n_prod ELSE m.n_replay END;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '056: portion rows differ from the manifest: %', v_bad; END IF;
  -- the live verified rows' new measures wait for sign-off: proposed, never active
  IF (SELECT count(*) FROM public.portion_units WHERE source IN ('usda_foundation', 'usda_sr', 'usda_fndds') AND status = 'proposed')
     <> (CASE WHEN v_go THEN 162 ELSE 0 END)
     OR EXISTS (SELECT 1 FROM public.portion_units pu JOIN _need056 n ON n.fdc_id = pu.fdc_id
                 WHERE pu.source IN ('usda_foundation', 'usda_sr', 'usda_fndds') AND pu.status <> 'proposed') THEN
    RAISE EXCEPTION '056: the measures for live verified rows must ship proposed (162)';
  END IF;
  IF (SELECT count(*) FROM public.portion_units WHERE source IN ('usda_foundation', 'usda_sr', 'usda_fndds') AND is_default)
     <> (CASE WHEN v_go THEN 5207 ELSE 5196 END) THEN
    RAISE EXCEPTION '056: default servings differ from the manifest (5207; replay 5196)';
  END IF;
  SELECT count(*) INTO v_n FROM public.portion_category_map m JOIN _map056 x USING (food_item_id);
  IF v_n <> 667 THEN RAISE EXCEPTION '056: % category map rows, manifest says 667', v_n; END IF;
  -- 2. privileges: server-side only
  IF has_function_privilege('anon', 'public.search_usda_local(text, integer)', 'EXECUTE')
     OR has_function_privilege('authenticated', 'public.search_usda_local(text, integer)', 'EXECUTE')
     OR NOT has_function_privilege('service_role', 'public.search_usda_local(text, integer)', 'EXECUTE')
     OR NOT has_function_privilege('service_role', 'public.food_search_text(text)', 'EXECUTE')
     OR has_function_privilege('anon', 'public.food_search_text(text)', 'EXECUTE')
     OR NOT has_function_privilege('service_role', 'extensions.strict_word_similarity(text, text)', 'EXECUTE')
     OR NOT has_table_privilege('service_role', 'public.food_items', 'SELECT') THEN
    RAISE EXCEPTION '056: search_usda_local / food_search_text privileges are wrong';
  END IF;
  -- 3. a total order under a hostile session threshold (the function pins its own). The forced-sequential-scan pass took
  --    4-5 s while this transaction holds SHARE on food_items, so it runs outside the migration:
  --    scripts/usda/check_056_determinism.sql (generated with the same probes), before the push on a copy and after it.
  FOR i IN 1..2 LOOP
    IF i = 2 THEN
      PERFORM pg_catalog.set_config('pg_trgm.strict_word_similarity_threshold', '0.9', true);
    END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_array(p.ord, s.id, s.score) ORDER BY p.ord, s.o), '[]') INTO v_cur
      FROM unnest(v_probe) WITH ORDINALITY AS p(q, ord)
      CROSS JOIN LATERAL (SELECT x.*, row_number() OVER () AS o FROM public.search_usda_local(p.q, 10) x) s;
    v_run := v_run || v_cur;
  END LOOP;
  PERFORM pg_catalog.set_config('pg_trgm.strict_word_similarity_threshold', '0.5', true);
  IF v_run[1] IS DISTINCT FROM v_run[2] THEN
    RAISE EXCEPTION '056: search_usda_local is not deterministic across session settings';
  END IF;
  IF pg_catalog.jsonb_array_length(v_run[1]) = 0 THEN RAISE EXCEPTION '056: search_usda_local finds nothing for the probes'; END IF;
  -- 4. it never returns a keyed row (they are search_foods'), and search_foods never returns an imported row
  IF EXISTS (SELECT 1 FROM unnest(v_probe) p(q) CROSS JOIN LATERAL public.search_usda_local(p.q, 10) s
              JOIN public.food_items fi ON fi.id = s.id WHERE fi.normalized_name IS NOT NULL)
     OR EXISTS (SELECT 1 FROM unnest(v_probe) p(q) CROSS JOIN LATERAL public.search_foods(p.q, 10) s
              JOIN public.food_items fi ON fi.id = s.id WHERE fi.normalized_name IS NULL) THEN
    RAISE EXCEPTION '056: search_usda_local and search_foods overlap';
  END IF;
  FOR r IN SELECT p.q, string_agg(s.name || ' [' || s.dataset || '] ' || round(s.score::numeric, 2), ' | ' ORDER BY s.o) AS top
             FROM unnest(ARRAY['rice', 'apple', 'chicken curry', 'oatmeal']) AS p(q)
             CROSS JOIN LATERAL (SELECT x.*, row_number() OVER () AS o FROM public.search_usda_local(p.q, 3) x) s GROUP BY p.q ORDER BY p.q
  LOOP
    RAISE NOTICE '056 probe % -> %', r.q, r.top;
  END LOOP;
  RAISE NOTICE '056 ok: % USDA portion rows (% default servings), % category map rows; search_usda_local deterministic on % probes; mode %',
    (SELECT count(*) FROM public.portion_units WHERE source IN ('usda_foundation', 'usda_sr', 'usda_fndds')),
    (SELECT count(*) FROM public.portion_units WHERE source IN ('usda_foundation', 'usda_sr', 'usda_fndds') AND is_default),
    667, pg_catalog.array_length(v_probe, 1), CASE WHEN v_go THEN 'production' ELSE 'replay' END;
END
$chk$;

NOTIFY pgrst, 'reload schema';
